const p = $input.first().json || {};
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';
const toText = (v) => isBlank(v) ? null : String(v).trim();
const toBool = (v) => {
  if (isBlank(v)) return null;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true','1','yes','sim'].includes(s)) return true;
  if (['false','0','no','nao','não'].includes(s)) return false;
  return null;
};
const toNumber = (v) => {
  if (isBlank(v)) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const normalizeHora = (raw) => {
  if (isBlank(raw)) return null;
  const s = String(raw).trim();
  let m = s.match(/^(\d{1,2}):(\d{2})/);
  if (m) return `${m[1].padStart(2, '0')}:${m[2]}`;
  m = s.match(/^(\d{1,2})h(\d{2})?$/i);
  if (m) return `${m[1].padStart(2, '0')}:${(m[2] || '00').padStart(2, '0')}`;
  try {
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false });
    }
  } catch {}
  return s;
};
const parseJson = (val) => {
  if (isBlank(val)) return null;
  if (Array.isArray(val)) return val.length ? JSON.stringify(val) : null;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      if (Array.isArray(parsed) && parsed.length) return JSON.stringify(parsed);
    } catch {}
  }
  return null;
};
const out = {};
const textFields = ['os_codigo','os_id_bomsaldo','conversa_id','tecnico_id','tecnico_nome','tecnico_whatsapp','cliente_nome','cliente_codigo','cliente_endereco','equipamento','equipamento_codigo','marca','modelo','defeito','causa','solucao','relatorio_tecnico','tipo_servico','servico_nome','servico_codigo','observacoes_orientacao','tipo_pagamento','forma_pagamento_id','link_pasta_drive','status_os','fase_ia','motivo_cancelamento','criado_em','atualizado_em','fechado_em'];
const numberFields = ['valor_total','qtd_evidencias','qtd_interacoes_ia','tempo_atendimento_min'];
const boolFields = ['em_garantia','checkin_registrado','checkout_registrado','ia_acertou_primeira','houve_revisao_manual','erro_integracao_api'];
for (const f of textFields) { if (!isBlank(p[f])) out[f] = toText(p[f]); }
for (const f of numberFields) { const n = toNumber(p[f]); if (n !== null) out[f] = n; }
for (const f of boolFields) { const b = toBool(p[f]); if (b !== null) out[f] = b; }
if (!isBlank(p.hora_entrada)) out.hora_entrada = normalizeHora(p.hora_entrada);
if (!isBlank(p.hora_saida)) out.hora_saida = normalizeHora(p.hora_saida);
if (!isBlank(p.status_os)) out.status_os = toText(p.status_os).toLowerCase();
if (!isBlank(p.fase_ia)) out.fase_ia = toText(p.fase_ia).toLowerCase();
const pj = parseJson(p.produtos_json); if (pj) out.produtos_json = pj;
const sj = parseJson(p.servicos_json); if (sj) out.servicos_json = sj;
out.os_codigo = toText(p.os_codigo);
if (!out.os_codigo) { throw new Error('os_codigo e obrigatorio para salvar contexto.'); }
out._tem_os_id = !isBlank(out.os_id_bomsaldo);
return [{ json: out }];

const novos = $('Validar Params').first().json;
const existente = $input.first().json;
const merged = { ...existente };
for (const key in novos) {
  if (novos[key] !== null && novos[key] !== undefined && novos[key] !== '') {
    merged[key] = novos[key];
  }
}
merged.atualizado_em = new Date().toISOString();
delete merged.id;
delete merged.criado_em;
if (merged.hora_entrada) merged.hora_entrada = String(merged.hora_entrada).trim();
if (merged.hora_saida) merged.hora_saida = String(merged.hora_saida).trim();
return [{ json: merged }];

const novos = $('Validar Params').first().json;
const out = { ...novos };
out.fase_ia = out.fase_ia || 'identificacao';
out.status_os = out.status_os || 'aberta';
out.atualizado_em = new Date().toISOString();
delete out.id;
delete out.criado_em;
if (out.hora_entrada) out.hora_entrada = String(out.hora_entrada).trim();
if (out.hora_saida) out.hora_saida = String(out.hora_saida).trim();
return [{ json: out }];

let r = {};
try { r = $input.first().json || {}; } catch {}
const p = $('Validar Params').first().json;

if (r.sucesso === false || r.error) {
  return [{ json: {
    sucesso: false,
    os_codigo: r.os_codigo || p.os_codigo,
    os_id_bomsaldo: r.os_id_bomsaldo || p.os_id_bomsaldo || null,
    mensagem: r.erro || r.error || 'Falha ao salvar contexto.'
  }}];
}

const foiInsert = r.id !== undefined && r.os_id_bomsaldo !== undefined;

if (foiInsert && !r.os_id_bomsaldo && !p._tem_os_id) {
  return [{ json: {
    sucesso: false,
    erro: 'OS registrada localmente sem os_id_bomsaldo. A OS ainda nao foi criada no Bom Saldo.',
    os_codigo: r.os_codigo || p.os_codigo,
    os_id_bomsaldo: null,
    acao: 'INSERT_SEM_OS_ID',
    mensagem: 'Chame criarOS antes de salvarContexto.'
  }}];
}

return [{ json: {
  sucesso: true,
  acao: foiInsert ? 'INSERT' : 'UPDATE',
  os_codigo: r.os_codigo || p.os_codigo,
  os_id_bomsaldo: r.os_id_bomsaldo || p.os_id_bomsaldo || null,
  fase_ia: r.fase_ia || p.fase_ia || 'identificacao',
  status_os: r.status_os || p.status_os || 'aberta',
  tecnico_id: r.tecnico_id || p.tecnico_id || null,
  cliente_codigo: r.cliente_codigo || p.cliente_codigo || null,
  atualizado_em: r.atualizado_em || new Date().toISOString(),
  mensagem: 'Contexto OS #' + (r.os_codigo || p.os_codigo) + ' salvo com sucesso.'
}}];

// Valida e filtra apenas campos com valor
const p = $input.first().json;

if (!p.os_codigo) {
  throw new Error('ERRO: os_codigo e OBRIGATORIO para salvar contexto.');
}

const out = { os_codigo: String(p.os_codigo) };

const camposStr = [
  'os_id_bomsaldo', 'conversa_id',
  'tecnico_id', 'tecnico_nome', 'tecnico_whatsapp',
  'cliente_nome', 'cliente_codigo', 'cliente_endereco',
  'equipamento', 'equipamento_codigo', 'marca', 'modelo',
  'defeito', 'causa', 'solucao', 'relatorio_tecnico',
  'tipo_servico', 'servico_nome', 'servico_codigo', 'observacoes_orientacao',
  'tipo_pagamento', 'forma_pagamento_id',
  'hora_entrada', 'hora_saida',
  'link_pasta_drive',
  'status_os', 'fase_ia', 'motivo_cancelamento',
  'produtos_json', 'servicos_json'
];

for (const campo of camposStr) {
  if (p[campo] !== undefined && p[campo] !== null && p[campo] !== '') {
    out[campo] = String(p[campo]);
  }
}

// Campos numericos
if (p.valor_total !== undefined && p.valor_total !== null && p.valor_total !== '') {
  out.valor_total = Number(p.valor_total) || 0;
}

// Campo boolean
if (p.em_garantia !== undefined && p.em_garantia !== null && p.em_garantia !== '') {
  out.em_garantia = (p.em_garantia === 'true' || p.em_garantia === true);
}

// Campos JSON - produtos_json e servicos_json
// Aceita string JSON ou array diretamente
const parseJSON = (val) => {
  if (!val || val === '') return null;
  if (Array.isArray(val)) return val.length > 0 ? JSON.stringify(val) : null;
  if (typeof val === 'string') {
    try { const arr = JSON.parse(val); return Array.isArray(arr) && arr.length > 0 ? val : null; } catch { return null; }
  }
  return null;
};

const pj = parseJSON(p.produtos_json);
if (pj) out.produtos_json = pj;

const sj = parseJSON(p.servicos_json);
if (sj) out.servicos_json = sj;

// Flag interna
out._tem_os_id = !!(out.os_id_bomsaldo && out.os_id_bomsaldo !== '');

return [{ json: out }];

// Merge: manter existente, sobrescrever com novos valores não-nulos
const novos = $('Validar Params').first().json;
const existente = $input.first().json;
const merged = { ...existente };

for (const key in novos) {
  if (novos[key] !== null && novos[key] !== undefined && novos[key] !== '') {
    merged[key] = novos[key];
  }
}

merged.atualizado_em = new Date().toISOString();
delete merged.id;
delete merged.criado_em;

// Normalizar hora_entrada e hora_saida para texto simples HH:MM
// Coluna agora é text - aceita qualquer formato legivel
const normalizeHora = (raw) => {
  if (!raw || raw === '') return null;
  const s = String(raw).trim();
  // Já é HH:MM ou HH:MM:SS
  const mColon = s.match(/^(\d{1,2}):(\d{2})/);
  if (mColon) return `${mColon[1].padStart(2,'0')}:${mColon[2]}`;
  // HHhMM ou HHh
  const mH = s.match(/^(\d{1,2})h(\d{2})?$/i);
  if (mH) return `${mH[1].padStart(2,'0')}:${(mH[2]||'00').padStart(2,'0')}`;
  // ISO timestamp - extrair hora no fuso SP
  try {
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return d.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false});
    }
  } catch {}
  return s;
};

if (merged.hora_entrada) merged.hora_entrada = normalizeHora(merged.hora_entrada) || merged.hora_entrada;
if (merged.hora_saida) merged.hora_saida = normalizeHora(merged.hora_saida) || merged.hora_saida;

return [{ json: merged }];

// Preparar INSERT de nova OS
const novos = $('Validar Params').first().json;
const out = { ...novos };
out.fase_ia = out.fase_ia || 'identificacao';
out.status_os = out.status_os || 'aberta';

// Normalizar hora para texto simples HH:MM (coluna é text)
const normalizeHora = (raw) => {
  if (!raw || raw === '') return null;
  const s = String(raw).trim();
  const mColon = s.match(/^(\d{1,2}):(\d{2})/);
  if (mColon) return `${mColon[1].padStart(2,'0')}:${mColon[2]}`;
  const mH = s.match(/^(\d{1,2})h(\d{2})?$/i);
  if (mH) return `${mH[1].padStart(2,'0')}:${(mH[2]||'00').padStart(2,'0')}`;
  try {
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return d.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false});
    }
  } catch {}
  return s;
};

if (out.hora_entrada) out.hora_entrada = normalizeHora(out.hora_entrada) || out.hora_entrada;
if (out.hora_saida) out.hora_saida = normalizeHora(out.hora_saida) || out.hora_saida;

return [{ json: out }];

let r = {};
try { r = $input.first().json || {}; } catch {}
const p = $('Validar Params').first().json;

// Detectar se foi INSERT (OS nao existia no banco)
// Se o Supabase INSERT retornou o registro, ele tera 'id' (pk do Supabase)
const foiInsert = r.id !== undefined && r.os_id_bomsaldo !== undefined;

// ALERTA: INSERT sem os_id_bomsaldo = OS nao criada no Bom Saldo ainda
// Isso significa que a Vanda chamou salvarContexto antes de criarOS
if (foiInsert && !r.os_id_bomsaldo && !p._tem_os_id) {
  return [{ json: {
    sucesso: false,
    erro: 'OS registrada localmente sem os_id_bomsaldo. A OS ainda NAO foi criada no Bom Saldo. Use a tool criarOS primeiro, depois salvarContexto.',
    os_codigo: r.os_codigo || p.os_codigo,
    os_id_bomsaldo: null,
    acao: 'INSERT_SEM_OS_ID',
    mensagem: 'ERRO: Chame criarOS antes de salvarContexto. Sem os_id_bomsaldo a OS nao existe no sistema ERP.'
  }}];
}

return [{ json: {
  sucesso: true,
  os_codigo: r.os_codigo || p.os_codigo,
  os_id_bomsaldo: r.os_id_bomsaldo || p.os_id_bomsaldo || null,
  fase_ia: r.fase_ia || p.fase_ia || 'identificacao',
  status_os: r.status_os || p.status_os || 'aberta',
  tecnico_id: r.tecnico_id || p.tecnico_id || null,
  cliente_codigo: r.cliente_codigo || p.cliente_codigo || null,
  mensagem: 'Contexto OS #' + (r.os_codigo || p.os_codigo) + ' salvo com sucesso.'
}}];
